bool MyApp::OnStartUp()
{
  // 1. Mandatory AppCasting startup boilerplate [1, 6]
  AppCastingMOOSApp::OnStartUp();

  list<string> params;
  m_MissionReader.GetConfiguration(GetAppName(), params);

  // 2. Check if the configuration block exists at all [1, 2]
  if(params.empty())
    reportConfigWarning("No configuration block found for " + GetAppName());

  for(string line : params) {
    string orig  = line;           // Save original line for error reporting [1]
    string param = toupper(biteStringX(line, '=')); // Parameters are case-insensitive [1, 7]
    string value = line;           // Remaining string is the value

    if(param == "THRESHOLD") {
