    }
    // 4. Handle typos and unknown parameters [1, 2, 10]
    else {
      reportUnhandledConfigWarning(orig); 
    }
  }

  // 5. Ensure the app registers for the mail it needs [5, 11]
  registerVariables();
  return true;
}

